package com.erni.finalanswer.rareminds;

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.audio.Sound;
import com.badlogic.gdx.utils.Disposable;
import java.util.*;

/**
 * The host's spoken lines in RARE MINDS, in the cloned host voice (generated by tools/host-tts/scripts/rare_minds_vo.py
 * into assets/rare_minds/voice/). Each cue has a few takes, picked at random without repeating the last one; a missing
 * file is simply skipped (the subtitle still shows).
 */
final class RareMindsVoice implements Disposable {
    private final Map<String,List<Sound>> takes=new HashMap<>();private final Map<String,Integer> last=new HashMap<>();
    RareMindsVoice(){
        String lang=com.erni.finalanswer.localization.Localization.russian()?"ru":"en";
        for(String cue:new String[]{"look","points"}){List<Sound> l=new ArrayList<>();
            for(int i=0;i<4;i++){var f=Gdx.files.internal("rare_minds/voice/"+lang+"/"+cue+"_"+i+".wav");if(f.exists())try{l.add(Gdx.audio.newSound(f));}catch(RuntimeException ignored){}}
            takes.put(cue,l);}
    }
    void say(String cue){List<Sound> l=takes.getOrDefault(cue,List.of());if(l.isEmpty())return;int k=new Random().nextInt(l.size());if(l.size()>1&&last.getOrDefault(cue,-1)==k)k=(k+1)%l.size();last.put(cue,k);try{l.get(k).play(.95f);}catch(RuntimeException ignored){}}
    @Override public void dispose(){for(var l:takes.values())for(Sound s:l)s.dispose();}
}
